import pandas as pd
import numpy as np

ii = pd.IntervalIndex.from_breaks([0,1,2,3,4])
iarr = pd.array(list(ii), dtype=ii.dtype)

df = pd.DataFrame({'a':['foo','foo','bar','bar'], 'b':['one','two','one','two'], 'c': iarr})

# 1) columns path (has columns='b')
res1 = {'stage':'has_columns'}
try:
    out1 = df.pivot_table(index='a', columns='b', values='c', aggfunc=lambda x: x.iloc[0], margins=True)
    res1.update({'ok': True, 'dtypes': {k: str(v) for k,v in out1.dtypes.items()}, 'columns': list(out1.columns), 'index': list(out1.index)})
    # record All cell value for each column
    if 'All' in out1.index:
        for col in out1.columns:
            res1[f"All_{col}"] = out1.loc['All', col]
except Exception as e:
    res1.update({'ok': False, 'exc_type': type(e).__name__, 'exc_msg': str(e)})

# 2) no-columns path (columns parameter omitted)
res2 = {'stage':'no_columns'}
try:
    out2 = df.pivot_table(index='a', values='c', aggfunc=lambda x: x.iloc[0], margins=True)
    res2.update({'ok': True, 'dtypes': {k: str(v) for k,v in out2.dtypes.items()}, 'index': list(out2.index)})
    if 'All' in out2.index:
        res2['All_c'] = out2.loc['All', 'c']
except Exception as e:
    res2.update({'ok': False, 'exc_type': type(e).__name__, 'exc_msg': str(e)})

# 3) mixed EA+numeric values=['c','d'] no-columns
res3 = {'stage':'mixed_no_columns'}
df2 = df.copy()
df2['d'] = [1.0,2.0,3.0,4.0]
try:
    out3 = df2.pivot_table(index='a', values=['c','d'], aggfunc=lambda x: x.iloc[0], margins=True)
    res3.update({'ok': True, 'dtypes': {k: str(v) for k,v in out3.dtypes.items()}, 'index': list(out3.index)})
    if 'All' in out3.index:
        res3['All_c'] = out3.loc['All','c']
        res3['All_d'] = out3.loc['All','d']
except Exception as e:
    res3.update({'ok': False, 'exc_type': type(e).__name__, 'exc_msg': str(e)})

probe('interval_margins_direct', {'res1': res1, 'res2': res2, 'res3': res3})

